// Version-Check: pr\u00fcft beim Start ob eine neue Version vorliegt und erzwingt Reload
const APP_BUILD = "462";
(function checkForUpdate() {
  if (location.hostname === 'localhost' || location.hostname === '127.0.0.1') return;
  const BUILD_GUARD_KEY = 'kompass-build-reload-guard-' + APP_BUILD;
  if (sessionStorage.getItem(BUILD_GUARD_KEY)) return; // schon einmal neu geladen \u2013 kein Loop
  fetch("./version.json?t=" + Date.now(), { cache: "no-store" })
    .then(r => r.json())
    .then(data => {
      if (data && data.build && data.build !== APP_BUILD) {
        sessionStorage.setItem(BUILD_GUARD_KEY, '1'); // vor dem Reload setzen!
        if ("caches" in window) {
          caches.keys().then(keys => Promise.all(keys.map(k => caches.delete(k))))
            .then(() => { window.location.reload(true); });
        } else {
          window.location.reload(true);
        }
      }
    })
    .catch(() => {}); // kein Netz \u2192 still ignorieren
})();
const PROFILE_KEY = "enneagramm-kompass:profile";
const VISITED_KEY = "enneagramm-kompass:visited";
const TIER_KEY    = "enneagramm-kompass:tier";
const NAME_KEY    = "enneagramm-kompass:lizenz-name";
const PHOTO_KEY   = "enneagramm-kompass:user-photo";

const KOMPASS_CODES = new Set([]);

function getUserPhoto()   { return localStorage.getItem(PHOTO_KEY) || ""; }
function setUserPhoto(d) { try { localStorage.setItem(PHOTO_KEY, d); } catch(e) {} }
function delUserPhoto()  { localStorage.removeItem(PHOTO_KEY); }

function getTier()        { return localStorage.getItem(TIER_KEY) || "demo"; }
function setTier(t)       { localStorage.setItem(TIER_KEY, t); }
function getLizenzName()  { return localStorage.getItem(NAME_KEY) || ""; }
function setLizenzName(n) { localStorage.setItem(NAME_KEY, n); }
function hasBasis()      { const t = getTier(); return t === "basis" || t === "heilwissen"; }
function hasHeilwissen() { return getTier() === "heilwissen"; }

